"""Render completed R62 scorecard; does not run measurements or change Git."""
from pathlib import Path
import json,sys
s=json.loads(Path(sys.argv[1]).read_text());out=Path(sys.argv[2]);p=s['primary'];ref=p['reference_seconds'];before=p['medians']['before'];after=p['medians']['after'];comparison=p['comparisons']['after_over_before']
lines=['# R62: captured locals-pointer locality','',f"Candidate compiler: `{s['static']['after']['source']}`. Baseline R61 compiler: `{s['static']['before']['source']}`. Only GPU was rebuilt; every other production library hash, feature set and profile is unchanged.",'',f"The complete eight-byte level-12 call measured **{after['multiple_of_reference']:.6f}× the reference**, from **{before['multiple_of_reference']:.6f}×** in the matched baseline cohort. Candidate/baseline elapsed is **{comparison['pooled_ratio']:.8f}×** ({s['changes_percent']['primary_seconds']:+.4f}%). Reference median: {ref*1000:.6f} ms.",'','The candidate stores the already validated program-entry locals pointer once in an invocation-owned stack slot and reloads that snapshot at each ordinary source-block entry. It does not reread the callback-visible Frame pointer. Non-program lowering is unchanged. The existing conservative visit-template verification includes the added reload; emitted machine stack and code are measured normally. This changes generated pointer transport, not compressor source, allocation behavior or logical resource charges.','', '| Metric | Reference | R61 baseline | R62 candidate | Change |','|---|---:|---:|---:|---:|',f"| Primary elapsed (ms) | {ref*1000:.6f} | {before['seconds']*1000:.6f} | {after['seconds']*1000:.6f} | {s['changes_percent']['primary_seconds']:+.4f}% |"]
for section,key,label in [('cpu','instructions','Retired instructions'),('cpu','cycles','CPU cycles'),('allocation','allocation_requests','Allocation requests'),('allocation','requested_bytes','Requested bytes'),('allocation','reallocations','Reallocations'),('allocation','peak_live_usable','Peak allocator live usable bytes'),('allocation','incremental_peak_live_usable','Incremental peak live usable bytes'),('cpu','rss_after','RSS after call'),('cpu','physical_after','Physical footprint after call')]:
 values=[s[section][variant][key]['median'] for variant in ['reference','before','after']];change=s['changes_percent'][key];lines.append('| '+label+' | '+' | '.join(f'{v:,.1f}' if int(v)!=v else f'{v:,.0f}' for v in values)+' | '+('—' if change is None else f'{change:+.4f}%')+' |')
diagnostic=s['diagnostic_cpu_elapsed']
lines+=['',f"The separate CPU-counter cohort elapsed is {diagnostic['before']['median_seconds']*1000:.6f} → {diagnostic['after']['median_seconds']*1000:.6f} ms ({diagnostic['change_percent']:+.6f}%). All 32 observations per variant are excluded from primary elapsed. This diagnostic elapsed is retained independently of the matched primary result."]
lines+=['','Primary elapsed, CPU counters, allocation counters and sampling are separate serialized cohorts. Their percentages are not multiplied or combined into a synthetic result. Requested bytes measure allocation requests, not initialized bytes copied. Allocator peak and post-call OS footprint are distinct measures; retained compiler/catalog/image storage is included.','', '## Matched pairs and contrary observations','', '| Pair | Baseline ms | Candidate ms | Candidate/baseline |','|---|---:|---:|---:|']
for group in p['groups']:lines.append(f"| {group['group']} | {group['medians']['before']*1000:.6f} | {group['medians']['after']*1000:.6f} | {group['after_over_before']:.8f}× |")
lines+=['',f"{comparison['improving_groups']}/4 independently prepared pairs and {comparison['improving_blocks']}/64 alternating blocks improve. Each pair has 16 blocks ×31 measured calls per variant: 3,968 total primary observations. Individual blocks within a prepared pair are descriptive, not independent experiments.",'', 'Counter directions that increased are retained below; an empty object means no listed median increased:','', '```json',json.dumps(s['contrary_counter_directions'],indent=2),'```','', '## Generated binary','', '| Metric | R61 baseline | R62 candidate |','|---|---:|---:|']
for key,label in [('code_bytes','Generated text bytes'),('stack_bytes','Machine entry stack bytes'),('typed_ir_version','Typed IR version'),('abi_version','ABI version')]:lines.append(f"| {label} | {s['static']['before'][key]:,} | {s['static']['after'][key]:,} |")
audit=s['binary_audit']
lines+=['',f"The actual linked Objects change generated text by {audit['code_bytes']['delta']:+,} bytes and machine entry stack by {audit['stack_bytes']['delta']:+,} bytes. UDIV is {audit['UDIV']['before']} → {audit['UDIV']['after']}. Full encoded instruction and pointer-access deltas appear in the independently pinned binary audit below. These static counts are not dynamic visits or hardware counter savings."]
roles=audit.get('pointer_roles',{})
if audit.get('historical_role_count_correction'):
 locals_counts=roles['locals']['loads'];argument_counts=roles['arguments']['loads']
 lines+=['','Pointer-role attribution correction: the older disassembly counter missed immediate updates to x16 and assigned some stack loads to a stale offset. The corrected R61 baseline contains '+format(locals_counts['before'],',')+' locals-pointer loads and '+format(argument_counts['before'],',')+' argument-lane-pointer loads, superseding the earlier 165,897 and 31,199 figures. R62 contains '+format(locals_counts['after'],',')+' and '+format(argument_counts['after'],',')+', respectively. The corrected ledger supersedes prior role attribution; whole opcode/stack-access totals and all measured retired instructions, cycles and elapsed observations are unchanged. These are static role counts, not dynamic execution counts.']
lines+=['','The candidate Object is independently bound to its corresponding image and libraries. Equality with the baseline Object is not an acceptance requirement. Actual binary audit:','','```json',json.dumps(s['binary_audit'],indent=2),'```','', '## Correctness and unchanged workload','', 'The input is eight bytes `abcdefgh`; exact raw output remains `[75,76,74,78,73,77,75,207,0,0]`, with independent inflation. Output capacity remains 13 and is cleared/reused. The tree contains 262,144 U16 entries, the cache 1,500,513 U32 words, search depth is 300 and nice length 258. Input aliases, finite admission/error order, previous publication on failure and recovery remain covered. Logical work is 60,260,219,686 and comparison work 47,612; neither is a hardware instruction count. Final managed bytes and nodes remain zero.','', 'The source and bytecode are unchanged:','','```json',json.dumps(s['source_pins'],indent=2),'```','', '## Qualification','',f"Qualification status: **{s['validation'].get('status', 'passed' if s['validation']['all_required_checks_pass'] else 'failed')}**. Exact counts come from archived inventories and executed receipts. Batches overlap; they are not a sum of unique tests.",'', '| Receipt | Expected tests | Observed | Passed |','|---|---:|---:|---|']
for row in s['validation']['checks']:
 if row.get('inventory_only'):continue
 lines.append(f"| `{row['receipt']}` | {row.get('expected_tests','—')} | {row.get('observed_tests',row.get('cases','—'))} | {row['passed']} |")
coverage=s['validation'].get('runtime_coverage')
if coverage:
 lines+=['',coverage['scope'],'','The added callback-pointer snapshot regression executes against both original parent production and the candidate, each using the current regression source. The final fixture uses default compilation and derives its restore callback from the descriptor’s actual scalar admission frontier, so the pointer substitution spans the interior source blocks without assuming one callback per primitive. The measured compressor configuration is unchanged. The original 328-runtime and 34-CI batches remain recorded at their actual earlier test source; the later inventory has 329 runtime tests and the current CI selection executes 35. These overlapping batches are not added together as unique tests. The measured producer remains ded89a9c0014fe66734be22ee6a3170e7ec10448; the post-measurement production edit is pinned-rustfmt normalization, verified byte-for-byte before the new qualification builds.']
lines+=['','Skipped coverage:']
for row in s['validation']['skipped_coverage']:lines.append('- '+row.get('test',row.get('coverage'))+': '+row['disposition'])
lines+=['','Retained earlier failed attempts:']
for row in s['validation'].get('prior_failures',[]):lines.append('- '+row['receipt']+': '+row['disposition'])
if not s['validation'].get('prior_failures'):lines.append('None recorded in this round.')
lines+=['','Decision: '+s['decision']['status']+'. '+s['decision']['reason']]
lines+=['','## Replay','', 'Run `python3 reconstruct.py /new/empty/output/path` from this evidence packet. It verifies every archived receipt version, overlays versions chronologically and reproduces scorecard, profile and validation JSON. No compiler, compressor executable or performance rerun is required.','', 'This is a small-input complete-compression result. It does not establish larger-input throughput or a standalone minimum memory footprint. All directions and the retain/reject decision come from the observed R62 receipts and explicit decision record. No percentages from earlier rounds are combined into this result.','']
out.write_text('\n'.join(lines))
